void bt(vector<int>& a, vector<bool>& used, vector<int>& cur, vector<vector<int>>& out) {
  if ((int)cur.size() == (int)a.size()) { out.push_back(cur); return; }
  for (int i = 0; i < (int)a.size(); ++i) {
    if (used[i]) continue;
    used[i] = true; cur.push_back(a[i]);
    bt(a, used, cur, out);
    cur.pop_back(); used[i] = false;
  }
}

